</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to rewrite:
<original_code>
import java.io.*;

public class Main {
	public static void main(String arg[])throws Exception{
		BufferedReader bff = new BufferedReader(new InputStreamReader(System.in));
		long n = Long.parseLong(bff.readLine());
		System.out.println(ones(n));
	}
	private static int digs(long n){
		return (int) Math.log10(n) + 1;
	}
	private static long fillOne(int n){
		long res = 1;
		while(n-- > 1)
			res = res * 10 + 1;
		return res;
	}

	private static long ones (long n){
		if(n <= 6) return n;
		int dig = digs(n);
		long aux = fillOne(dig), one = aux, diff = n;
		int c = 0;
		//System.out.println(aux);
		while(aux < n){
			c++;
			diff = n - aux;
			aux += one;
		}
		//System.out.println(diff + " " + aux);
		long res;
		if(c > 0)
			res = Math.min(c*dig + ones(diff), ++c * dig + ones(aux - n));
		else
			res = ++c * dig + ones(aux - n);
		aux = fillOne(dig + 1);
		if(aux - n < n)
			res = Math.min(res, dig + 1 + ones(aux - n));
		return res;
	}
}

